-- Vendor provenance recovered from the old system's material inward.
--
-- The catalogue export carried no supplier, so every migrated item
-- arrived with vendor_id null -- there was no way to answer "who did we
-- buy this from". material_inward has it, keyed by item code, so it is
-- joined back on here.
--
-- Where an item appears on several inwards (13 do), the LATEST is used:
-- that is where the stock currently on the shelf came from. The MI
-- number and date go into description so the reference survives even if
-- the vendor row is later merged or renamed.
update items i set vendor_id = v.vendor_id::uuid,
       description = coalesce(nullif(btrim(i.description),''), v.note)
from (values
